<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {request,state} from '../store'
import type {NetworkCapture,NetworkRequest} from '../types'
import {dateTime} from '../uiHelpers'
const props=defineProps<{sessionId:string}>()
const capture=ref<NetworkCapture>(),rows=ref<NetworkRequest[]>([]),total=ref(0),offset=ref(0)
const query=ref(''),errorsOnly=ref(false),loading=ref(false),error=ref('')
const selected=ref(''),metadata=ref<Record<string,any>>(),body=ref<{content:string;note:string;nextOffset:number|null;totalCharacters:number}>()
const section=ref<'response_body'|'request_body'>('response_body'),bodyOffset=ref(0),bodyLoading=ref(false)
let listVersion=0,detailVersion=0
const levels:Record<string,string>={off:'关闭',api:'接口记录',detailed:'详细记录'}
const content=computed(()=>{const value=body.value?.content||'';try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}})
async function load(){const version=++listVersion;loading.value=true;error.value='';try{const result=await request('/tools/network_list',{arguments:{session_id:props.sessionId,query:query.value,errors_only:errorsOnly.value,offset:offset.value,limit:20}});if(version!==listVersion)return;capture.value=result.session;rows.value=result.requests;total.value=result.total}catch(e){if(version===listVersion)error.value=String(e)}finally{if(version===listVersion)loading.value=false}}
async function readBody(){if(!selected.value)return;const version=++detailVersion;bodyLoading.value=true;error.value='';try{const result=await request('/tools/network_read',{arguments:{session_id:props.sessionId,request_id:selected.value,section:section.value,offset:bodyOffset.value,limit:8000}});if(version===detailVersion)body.value=result}catch(e){if(version===detailVersion)error.value=String(e)}finally{if(version===detailVersion)bodyLoading.value=false}}
async function selectRow(id:string){selected.value=id;metadata.value=undefined;body.value=undefined;bodyOffset.value=0;const session=props.sessionId;try{const result=await request('/tools/network_read',{arguments:{session_id:session,request_id:id}});if(props.sessionId!==session||selected.value!==id)return;metadata.value=result;await readBody()}catch(e){error.value=String(e)}}
function search(){offset.value=0;void load()}
function page(delta:number){offset.value=Math.max(0,offset.value+delta);void load()}
function bodyPage(next:number){bodyOffset.value=next;void readBody()}
watch(section,()=>{bodyOffset.value=0;body.value=undefined;void readBody()})
watch(()=>[props.sessionId,state.projectId],()=>{listVersion++;detailVersion++;selected.value='';metadata.value=undefined;body.value=undefined;offset.value=0;query.value='';errorsOnly.value=false;capture.value=undefined;rows.value=[];void load()},{immediate:true})
</script>
<template><section class="network-panel" aria-label="浏览器网络请求">
<div class="network-heading"><div><strong>网络请求</strong><span v-if="capture" class="muted">{{levels[capture.level]}} · {{capture.count}} 条</span></div><button class="text-button" :disabled="loading" @click="load">{{loading?'加载中…':'刷新'}}</button></div>
<p class="form-hint">仅记录本次浏览器会话中的目标站点请求，点击一条查看详情。</p>
<p v-if="capture?.level==='off'" class="network-notice">本次网络记录已关闭。开启只影响后续操作，无法恢复过去的请求。</p>
<template v-else><form class="network-filter" @submit.prevent="search"><input v-model="query" aria-label="筛选网络请求" placeholder="筛选地址或请求方法"/><label><input v-model="errorsOnly" type="checkbox" @change="search"/>只看失败</label><button class="button secondary" :disabled="loading">查询</button></form>
<p v-if="capture?.dropped" class="network-notice">{{capture.dropped}} 条请求达到采集上限后未记录。</p><p v-if="capture?.error" class="network-notice">{{capture.error}}</p>
<div class="network-table-wrap"><table class="data-table network-table"><thead><tr><th>方法 / 地址</th><th>状态</th><th>耗时</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" :class="{selected:selected===row.id}"><td><button class="network-request" @click="selectRow(row.id)"><strong>{{row.method}}</strong><span :title="row.url">{{row.url}}</span></button><small class="muted">{{row.resourceType}} · {{dateTime(new Date(row.startedAt*1000).toISOString())}}</small></td><td><span class="network-status" :class="{failed:row.state==='failed'||(row.status||0)>=400}">{{row.state==='failed'?'连接失败':row.state==='incomplete'?'未完成':row.status??'等待响应'}}</span></td><td class="mono">{{row.durationMs==null?'—':row.durationMs+'ms'}}</td></tr></tbody></table></div>
<p v-if="!rows.length&&!loading" class="form-hint">{{capture?.status==='queued'?'等待浏览器开始采集':errorsOnly?'没有匹配的失败请求':'没有匹配的请求。接口记录默认只收集 XHR / fetch；页面资源可使用详细记录。'}}</p>
<div v-if="total" class="network-pagination"><span>{{offset+1}}–{{Math.min(offset+20,total)}} / {{total}}</span><button class="text-button" :disabled="!offset||loading" @click="page(-20)">上一页</button><button class="text-button" :disabled="offset+20>=total||loading" @click="page(20)">下一页</button></div>
</template>
<p v-if="error" class="inline-error" role="alert">{{error}}</p>
<section v-if="selected" class="network-detail"><div class="network-heading"><strong>{{metadata?.method}} {{selected}}</strong><button class="text-button" @click="selected='';detailVersion++">收起详情</button></div><p class="mono network-url">{{metadata?.url}}</p><p v-if="metadata?.step" class="form-hint">操作时所在步骤：{{metadata.step.index}}. {{metadata.step.name}}（后台请求也可能同时发生）</p><p v-if="metadata?.error" class="inline-error">{{metadata.error}}</p>
<div class="network-headers"><details><summary>请求头</summary><dl v-for="(value,key) in metadata?.requestHeaders" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></dl></details><details><summary>响应头</summary><dl v-for="(value,key) in metadata?.responseHeaders" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></dl></details></div>
<div class="local-tabs"><button :class="{active:section==='response_body'}" @click="section='response_body'">响应正文</button><button :class="{active:section==='request_body'}" @click="section='request_body'">请求正文</button></div><p v-if="bodyLoading" class="form-hint">读取正文中…</p><template v-else><p v-if="body?.note" class="network-notice">{{body.note}}</p><pre v-if="content" class="log-block network-body">{{content}}</pre><p v-else class="form-hint">没有保存的正文。</p><div v-if="body&&body.totalCharacters>8000" class="network-pagination"><span>{{bodyOffset+1}}–{{Math.min(bodyOffset+8000,body.totalCharacters)}} / {{body.totalCharacters}} 字符</span><button class="text-button" :disabled="!bodyOffset" @click="bodyPage(Math.max(0,bodyOffset-8000))">上一段</button><button class="text-button" :disabled="body.nextOffset==null" @click="bodyPage(body.nextOffset!)">下一段</button></div></template>
</section></section></template>
<style scoped>
.network-panel{min-width:0;padding:18px 0}.network-heading,.network-heading>div{display:flex;align-items:center;gap:12px;justify-content:space-between}.network-filter{display:flex;gap:10px;align-items:center;margin:16px 0}.network-filter>input{min-width:0;flex:1}.network-filter label{display:flex;align-items:center;gap:6px;white-space:nowrap;font-size:13px}.network-filter input[type=checkbox]{width:auto}.network-notice{padding:10px 12px;background:var(--surface-soft,#f5f6f8);border-left:3px solid #b8bdc6;font-size:13px;overflow-wrap:anywhere}.network-table-wrap{overflow:auto}.network-table{font-size:13px;min-width:0;width:100%;table-layout:fixed}.network-table th:first-child{width:62%}.network-table th:nth-child(2){width:16%}.network-table th:last-child{width:22%}.network-table td:first-child{max-width:360px}.network-request{display:flex;text-align:left;gap:8px;border:0;background:none;cursor:pointer;padding:0;color:inherit;max-width:100%;width:100%}.network-request span{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.network-request strong{color:#355a82;flex-shrink:0}.network-table tr.selected{background:var(--surface-soft,#f3f6fa)}.network-status{white-space:nowrap}.network-status.failed{color:#b23b35}.network-pagination{display:flex;gap:14px;justify-content:flex-end;align-items:center;font-size:12px;color:#6b7280;padding:12px 0}.network-detail{border-top:1px solid var(--border,#e1e4e8);margin-top:12px;padding-top:16px}.network-url{overflow-wrap:anywhere;font-size:12px}.network-headers{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:14px 0}.network-headers summary{cursor:pointer;font-size:13px}.network-headers dl{display:grid;gap:3px;font-size:12px;margin:10px 0;overflow-wrap:anywhere}.network-headers dt{font-weight:600}.network-headers dd{margin:0;color:#667085;white-space:pre-wrap}.network-body{max-height:420px;overflow:auto;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:700px){.network-filter{flex-wrap:wrap}.network-filter>input{flex-basis:100%}.network-headers{grid-template-columns:1fr}.network-table td:first-child{max-width:190px}}
</style>
